import {deflateRawSync} from 'node:zlib';
export function workbookFile(files){const parts=[],directory=[];let offset=0;for(const [name,content]of Object.entries(files)){const data=Buffer.from(content),compressed=deflateRawSync(data),nm=Buffer.from(name),local=Buffer.alloc(30);local.writeUInt32LE(0x04034b50);local.writeUInt16LE(8,8);local.writeUInt32LE(compressed.length,18);local.writeUInt32LE(data.length,22);local.writeUInt16LE(nm.length,26);parts.push(local,nm,compressed);const central=Buffer.alloc(46);central.writeUInt32LE(0x02014b50);central.writeUInt16LE(8,10);central.writeUInt32LE(compressed.length,20);central.writeUInt32LE(data.length,24);central.writeUInt16LE(nm.length,28);central.writeUInt32LE(offset,42);directory.push(central,nm);offset+=local.length+nm.length+compressed.length;}const dir=Buffer.concat(directory),end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50);end.writeUInt16LE(Object.keys(files).length,10);end.writeUInt32LE(dir.length,12);end.writeUInt32LE(offset,16);const b=Buffer.concat([...parts,dir,end]);return b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength);}

export const catalogWorkbook=()=>workbookFile({'xl/worksheets/sheet1.xml':'<worksheet><sheetData><row r="1"><c r="C1" t="inlineStr"><is><t>Customer</t></is></c><c r="D1" t="inlineStr"><is><t>Display Name</t></is></c></row><row r="2"><c r="C2"/><c r="D2" t="inlineStr"><is><t>Imported standalone</t></is></c></row></sheetData></worksheet>'});
